function enterCountry(i){state.country=countries[i];state.screen='game';state.x=120;state.y=105;state.character='Lucia';state.vehicle=null;state.walkers=[];for(let n=0;n<16;n++)state.walkers.push({x:Math.random()*1800-900,y:Math.random()*1800-900,a:Math.random()*Math.PI*2,c:['#dfb787','#db8d79','#8fc7ad'][n%3],t:Math.random()*8});for(let n=0;n<10;n++)state.traffic.push({x:Math.random()*2000-1000,y:Math.random()*2000-1000,a:Math.random()*6.28,c:['#e78062','#c6ce91','#7899ad'][n%3],s:40+Math.random()*25});$('#location').textContent=`${state.country.city.toUpperCase()} · ${state.country.home.toUpperCase()}`;$('#miniRegion').textContent=state.country.city.toUpperCase();$('#hud').style.display='block';closeOverlay();updateWeather();toast(state.country.hello);lastTime();draw()}
function lastTime(){let now=new Date();let hr=now.getHours();state.publicLights=hr>=18||hr<7}
function updateTime(){const d=new Date();$('#clock').innerHTML=`<b>${d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false})}</b> · ${d.toLocaleDateString([],{weekday:'short',day:'2-digit',month:'short'})}`;state.publicLights=d.getHours()>=18||d.getHours()<7;}
async function updateWeather(){let c=state.country;if(!c)return;try{let r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${c.lat}&longitude=${c.lon}&current=temperature_2m,weather_code,is_day&timezone=auto`);let j=await r.json(),code=j.current.weather_code;state.weather=(code===0?'CLEAR':code<50?'CLOUDY':code<70?'RAIN':'STORM');$('#weather').innerHTML=`${code<50?'◌':code<70?'☂':'ϟ'} &nbsp; ${state.weather} · ${Math.round(j.current.temperature_2m)}°C`}catch(e){let h=new Date().getHours();state.weather=h>17||h<6?'NIGHT':'CLEAR';$('#weather').innerHTML=`◌ &nbsp; ${state.weather} · LOCAL SKY`}}
function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
function resize(){let dpr=Math.min(devicePixelRatio||1,2),w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);mini.width=mini.clientWidth*dpr;mini.height=mini.clientHeight*dpr;mctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
const buildings=[];for(let gx=-1800;gx<1900;gx+=360)for(let gy=-1800;gy<1900;gy+=360){let seed=Math.abs(Math.sin(gx*12.3+gy*5.7)),kind=seed<.12?'park':seed>.85?'shop':'block';buildings.push({x:gx+26,y:gy+26,w:308,h:308,kind,seed})}
function roundRect(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.stroke()}}
function worldToScreen(x,y,cx,cy,scale,w,h){return {x:(x-cx)*scale+w/2,y:(y-cy)*scale+h/2}}
function drawWorld(){let w=canvas.clientWidth,h=canvas.clientHeight,zoom=state.camera===0?1.55:state.camera===3?.62:state.camera===4?.82:state.camera===2?.9:1;let cx=state.x,cy=state.y;if(state.camera===3){cx+=Math.cos(state.angle)*190;cy+=Math.sin(state.angle)*190}let sc=zoom;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);ctx.scale(sc,sc);ctx.translate(-cx,-cy);let night=state.publicLights;
ctx.fillStyle=night?'#192522':'#253b32';ctx.fillRect(cx-w/(2*sc)-100,cy-h/(2*sc)-100,w/sc+200,h/sc+200);
// street grid with curbs, lane markings, and textured sidewalks
for(let x=-2200;x<2200;x+=360){ctx.fillStyle='#414b48';ctx.fillRect(x-16,-2200,32,4400);ctx.fillStyle='#54605a';ctx.fillRect(x-20,-2200,4,4400);ctx.fillRect(x+16,-2200,4,4400);ctx.strokeStyle='#b9b69a55';ctx.setLineDash([18,19]);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x, -2200);ctx.lineTo(x,2200);ctx.stroke();ctx.setLineDash([])}
for(let y=-2200;y<2200;y+=360){ctx.fillStyle='#414b48';ctx.fillRect(-2200,y-16,4400,32);ctx.fillStyle='#54605a';ctx.fillRect(-2200,y-20,4400,4);ctx.fillRect(-2200,y+16,4400,4);ctx.strokeStyle='#b9b69a55';ctx.setLineDash([18,19]);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-2200,y);ctx.lineTo(2200,y);ctx.stroke();ctx.setLineDash([])}
for(const b of buildings){if(Math.abs(b.x-cx)>w/sc/2+400||Math.abs(b.y-cy)>h/sc/2+400)continue;if(b.kind==='park'){ctx.fillStyle='#385845';ctx.fillRect(b.x,b.y,b.w,b.h);for(let n=0;n<16;n++){let tx=b.x+20+(n*47%270),ty=b.y+18+(n*73%270);ctx.fillStyle='#67835a';ctx.beginPath();ctx.arc(tx,ty,7+(n%3),0,7);ctx.fill();ctx.fillStyle='#997453';ctx.fillRect(tx-1,ty+3,2,9)}}else{ctx.fillStyle='#888b7966';ctx.fillRect(b.x-6,b.y-6,b.w+12,b.h+12);let pad=state.country?.city==='Karachi'?'#9b795d':state.country?.city==='Miami'?'#a98c78':'#95897b';ctx.fillStyle=pad;ctx.fillRect(b.x,b.y,b.w,b.h);let inset=b.kind==='shop'?20:30;ctx.fillStyle=b.kind==='shop'?'#54544a':(b.seed>.5?'#766e61':'#666b61');ctx.fillRect(b.x+inset,b.y+inset,b.w-inset*2,b.h-inset*2);ctx.fillStyle='#d2bc9a';for(let ix=0;ix<3;ix++)for(let iy=0;iy<3;iy++){ctx.fillRect(b.x+inset+15+ix*74,b.y+inset+14+iy*75,22,12)}if(night){ctx.fillStyle='#f8c96c';ctx.globalAlpha=.55;ctx.fillRect(b.x+inset+15,b.y+inset+14,22,12);ctx.globalAlpha=1}if(b.kind==='shop'){ctx.fillStyle='#ed7c69';ctx.fillRect(b.x+105,b.y+8,95,9)}}}
// custom billboard and active poster crew near a city block
let bx=420,by=-145;ctx.fillStyle='#a8aaa0';ctx.fillRect(bx,by,7,90);ctx.fillRect(bx+176,by,7,90);ctx.fillStyle='#202e2c';ctx.fillRect(bx-5,by-58,194,61);ctx.fillStyle='#d3f66d';ctx.font='bold 17px Manrope';ctx.fillText('FIVE STAR',bx+17,by-29);ctx.fillStyle='#ff74ba';ctx.font='9px Manrope';ctx.fillText('THE CITY IS YOURS',bx+18,by-12);ctx.strokeStyle='#c2b9a2';ctx.lineWidth=2;ctx.strokeRect(bx-8,by-67,202,165);for(let k=0;k<2;k++){ctx.fillStyle='#d8a778';ctx.fillRect(bx+16+k*45,by+19+k*21,8,16);ctx.fillStyle='#384d45';ctx.fillRect(bx+15+k*45,by+35+k*21,10,15)}
// small paving variations / dirt lanes
ctx.fillStyle='#9b795055';ctx.fillRect(-155,-15,150,30);ctx.fillRect(205,345,155,30);ctx.restore();}
function drawEntity(x,y,a,color,isCar=false){ctx.save();ctx.translate(x,y);ctx.rotate(a);if(isCar){ctx.fillStyle='#101615';roundRect(ctx,-19,-10,38,20,5,true);ctx.fillStyle=color;roundRect(ctx,-16,-8,32,16,4,true);ctx.fillStyle='#30423d';roundRect(ctx,-7,-6,15,12,3,true);ctx.fillStyle='#f5df99';ctx.fillRect(13,-6,3,4);ctx.fillRect(13,2,3,4)}else{ctx.fillStyle='#111';ctx.beginPath();ctx.arc(0,0,7,0,7);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,-2,5,0,7);ctx.fill();ctx.fillStyle='#e7c2a4';ctx.beginPath();ctx.arc(0,-6,3,0,7);ctx.fill()}ctx.restore()}
function drawPlayer(){let w=canvas.clientWidth,h=canvas.clientHeight,scale=state.camera===0?1.55:state.camera===3?.62:state.camera===4?.82:state.camera===2?.9:1, p=worldToScreen(state.x,state.y,state.x,state.y,scale,w,h);if(state.camera===1){ctx.fillStyle='#192522';ctx.fillRect(0,0,w,h);ctx.fillStyle='#263a33';ctx.beginPath();ctx.moveTo(w*.17,h);ctx.lineTo(w*.36,h*.45);ctx.lineTo(w*.64,h*.45);ctx.lineTo(w*.83,h);ctx.fill();ctx.fillStyle='#46504b';ctx.fillRect(w*.45,h*.48,w*.1,h*.28);ctx.fillStyle='#e4c283';ctx.fillRect(w*.48,h*.52,w*.04,h*.04);ctx.fillStyle='#ddd';ctx.font='10px DM Mono';ctx.fillText('FIRST PERSON · PRESS C TO CHANGE CAMERA',20,h-24);return}for(let v of state.traffic){let p2=worldToScreen(v.x,v.y,state.x,state.y,scale,w,h);if(p2.x>-60&&p2.x<w+60&&p2.y>-60&&p2.y<h+60)drawEntity(p2.x,p2.y,v.a,v.c,true)}for(let npc of state.walkers){let p2=worldToScreen(npc.x,npc.y,state.x,state.y,scale,w,h);if(p2.x>-30&&p2.x<w+30&&p2.y>-30&&p2.y<h+30)drawEntity(p2.x,p2.y,npc.a,npc.c)}if(state.vehicle){drawEntity(p.x,p.y,state.angle,state.vehicle.color,true)}else drawEntity(p.x,p.y,state.angle,state.character==='Lucia'?'#e98489':'#8cb9a5')}

