function draw(){if(state.screen!=='game')return;drawWorld();drawPlayer();drawMarkers();drawMini();requestAnimationFrame(draw)}
let keys={},then=0;function frame(ts){requestAnimationFrame(frame);if(state.screen!=='game')return;let dt=Math.min(.05,(ts-then)/1000||0);then=ts;let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);if(state.vehicle){if(forward)state.speed=Math.max(-20,Math.min(150,state.speed+forward*48*dt));else state.speed*=Math.max(0,1-1.6*dt);if(side)state.angle+=side*dt*(state.speed<0?-1:1)*1.8;let v=state.speed/3.6;state.x+=Math.cos(state.angle)*v*dt;state.y+=Math.sin(state.angle)*v*dt;$('#speedVal').textContent=Math.round(Math.abs(state.speed));$('#speedBox').style.display='block';$('#activeRole').textContent=`${state.vehicle.name.toUpperCase()} · ${Math.round(state.speed)} KM/H`}else{let mag=Math.hypot(forward,side);if(mag){let vx=side*Math.cos(state.angle)-forward*Math.sin(state.angle),vy=side*Math.sin(state.angle)+forward*Math.cos(state.angle);state.x+=vx/mag*125*dt;state.y+=vy/mag*125*dt;state.angle=Math.atan2(vy,vx)}$('#speedBox').style.display='none';$('#activeRole').textContent=state.country.city.toUpperCase()+' · ON FOOT'}for(let n of state.walkers){n.t+=dt;if(n.t>2){n.t=0;n.a+=(Math.random()-.5)*1.6}n.x+=Math.cos(n.a)*12*dt;n.y+=Math.sin(n.a)*12*dt}updateTime()}
function closestPlace(){let found=null,d=Infinity;for(let p of places){let a=Math.hypot(state.x-p.x,state.y-p.y);if(a<d){d=a;found=p}}return d<95?found:null}
function interaction(){let p=closestPlace();if(state.vehicle){state.vehicle=null;state.speed=0;toast('Parked. You step out onto the street.');return}if(!p){let npc=state.walkers.find(n=>Math.hypot(n.x-state.x,n.y-state.y)<70);if(npc){toast(state.country.hello);return}toast('Nothing nearby. Follow the pink route to the Motor Club.');return}if(p.id==='home')houseMenu();if(p.id==='showroom')showroomMenu();if(p.id==='hospital')hospitalMenu();if(p.id==='police')policeMenu()}
function houseMenu(){overlay(`<div class="modal-head"><div><div class="eyebrow">${state.country.home.toUpperCase()}</div><h2>Home, your way.</h2><p>Public lights follow local time: on at 18:00 and off at 07:00. Your home is always yours to control.</p></div><button class="close" id="close">×</button></div><div class="menu-grid">${['Interior lights','Kitchen appliances','Bedroom lamp'].map((n,i)=>`<button class="menu-item" data-light="${i}"><b>${state.lights.house[i]?'● ON':'○ OFF'} &nbsp; ${n}</b><span>Manual safehouse switch · tap to toggle</span></button>`).join('')}</div><div class="btn-row"><span class="fineprint">Switches work independently of city lighting.</span><button class="btn secondary" id="homeClose">BACK TO STREET</button></div>`);$('#close').onclick=closeOverlay;$('#homeClose').onclick=closeOverlay;document.querySelectorAll('[data-light]').forEach(b=>b.onclick=()=>{state.lights.house[+b.dataset.light]=!state.lights.house[+b.dataset.light];houseMenu()})}
const cars=[{name:'Prism GT',desc:'Blue-to-pink fade · supercar',color:'#b47cbd',price:'$98,000',emoji:'✧'},{name:'C8 Fieldline',desc:'Camouflage · mid-engine coupe',color:'#87916d',price:'$76,500',emoji:'◈'},{name:'Orange Track',desc:'Track hypercar · launch control',color:'#ed8e45',price:'$142,000',emoji:'⌁'},{name:'Classic Verde',desc:'Green lowrider · chrome trim',color:'#579378',price:'$42,000',emoji:'◇'},{name:'Skyline E',desc:'Civilian flying Tesla · hover mode',color:'#b7d8d1',price:'$120,000',emoji:'✦'},{name:'Interceptor Air',desc:'Police flying Tesla · patrol livery',color:'#e4e6df',price:'—',emoji:'✚'}];
function showroomMenu(){overlay(`<div class="modal-head"><div><div class="eyebrow">MOTOR CLUB · SHOWROOM</div><h2>Pick your next ride.</h2><p>Choose any ride to take it for a test drive. The interceptor is an aerial patrol ride.</p></div><button class="close" id="close">×</button></div><div class="menu-grid">${cars.map((c,i)=>`<button class="menu-item" data-car="${i}"><b style="color:${c.color}">${c.emoji} &nbsp; ${c.name}</b><span>${c.desc}<br>${c.price} · Take for a spin</span></button>`).join('')}</div>`,true);$('#close').onclick=closeOverlay;document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>{state.vehicle={...cars[+b.dataset.car]};state.x=440;state.y=40;state.speed=0;state.angle=0;closeOverlay();toast(`${state.vehicle.name} ready. WASD to drive · E to park.`)})}

