 async function updateWeather(){let c=state.country;if(!c)return;try{let r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${c.lat}&longitude=${c.lon}&current=temperature_2m,weather_code,is_day&timezone=auto`);let j=await r.json(),code=j.current.weather_code;state.weather=(code===0?'CLEAR':code<50?'CLOUDY':code<70?'RAIN':'STORM');$('#weather').innerHTML=`${code<50?'◌':code<70?'☂':'ϟ'} &nbsp; ${state.weather} · ${Math.round(j.current.temperature_2m)}°C`}catch(e){let h=new Date().getHours();state.weather=h>17||h<6?'NIGHT':'CLEAR';$('#weather').innerHTML=`◌ &nbsp; ${state.weather} · LOCAL SKY`}}
