const {chromium}=require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{let b;try{b=await chromium.launch({headless:true});}catch(e){console.error('LAUNCH_FAIL',e.message);process.exit(2)}const p=await b.newPage({viewport:{width:1365,height:900}});let errs=[];p.on('pageerror',e=>errs.push(e.message));p.on('console',m=>{if(m.type()==='error')errs.push(m.text())});await p.goto('http://localhost:3002');await p.locator('#introContinue').click();await p.locator('#day2').fill('1');await p.locator('#month2').selectOption('1');await p.locator('#year2').fill('1990');await p.locator('#verifySkip').click();await p.waitForTimeout(1400);console.log('country buttons',await p.locator('[data-country]').count(),'errors',errs);await p.locator('[data-country="1"]').click();await p.waitForTimeout(500);console.log('game prompt:',await p.locator('#prompt').innerText(),'canvas size',await p.locator('#world').evaluate(c=>[c.width,c.height]));await p.keyboard.press('f');await p.waitForTimeout(100);console.log('active name',await p.locator('#activeName').innerText());await p.keyboard.press('c');await p.keyboard.press('p');console.log('phone dialog visible',await p.locator('.modal').count(),'errors',errs);await b.close()})().catch(e=>{console.error(e);process.exit(1)});
